{"command":"python3 -c "
import csv

# Read stops
stops = {}
with open('outputs/t05_clean_stops.csv', 'r', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stops[row['stop_id']] = row

# Read stop_times
stop_times = {}
with open('outputs/t05_clean_stop_times.csv', 'r', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stop_id = row['stop_id']
        if stop_id not in stop_times:
            stop_times[stop_id] = []
        stop_times[stop_id].append(row)

# Read trips
trips = {}
with open('trips.txt', 'r', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        trips[row['trip_id']] = row['route_id']

# Read output
with open('outputs/t06_stop_service_intensity.csv', 'r', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stop_id = row['stop_id']

        expected_n_departures = len(stop_times.get(stop_id, []))
        actual_n_departures = int(row['n_departures'])

        trip_ids = stop_times.get(stop_id, [])
        expected_n_routes = len(set(trips.get(tid, 'UNKNOWN') for tid in trip_ids))
        actual_n_routes = int(row['n_routes'])

        if stop_id in stop_times:
            times = sorted([t['departure_time'] for t in stop_times[stop_id]])
            expected_first = times[0]
            expected_last = times[-1]
            actual_first = row['first_departure']
            actual_last = row['last_departure']
        else:
            expected_first = ''
            expected_last = ''
            actual_first = ''
            actual_last = ''

        errors = []
        if expected_n_departures != actual_n_departures:
            errors.append(f'n_departures: {stop_id} expected={expected_n_departures} actual={actual_n_departures}')
        if expected_n_routes != actual_n_routes:
            errors.append(f'n_routes: {stop_id} expected={expected_n_routes} actual={actual_n_routes}')
        if expected_first != actual_first:
            errors.append(f'first_departure: {stop_id} expected={expected_first} actual={actual_first}')
        if expected_last != actual_last:
            errors.append(f'last_departure: {stop_id} expected={expected_last} actual={actual_last}')

        if errors:
            for e in errors:
                print(e)
        else:
            print(f'{stop_id}: OK')

print('Verification complete!')
""}

